다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int main(void) {
    int a = 19, b = 12;
    int *p = &a;
    *p = *p - b;
    p = &b;
    *p = a - 4;
    (*p)++;
    printf("%d %d", a, b);
    return 0;
}

