다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
void sv(int x, int y) {
    int t = x;
    x = y;
    y = t;
}
void sp(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}
int main(void) {
    int a = 5, b = 8;
    int c = 6, d = 9;
    sv(a, b);
    sp(&c, &d);
    printf("%d %d %d %d", a, b, c, d);
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
int calc(int *u, int v) {
    *u = *u - v;
    v = v * 3;
    return v - *u;
}
int main(void) {
    int a = 13, b = 5;
    int r = calc(&a, b);
    printf("%d %d %d", r, a, b);
    return 0;
}

다음 C 프로그램의 실행 결과는?

[코드]
#include <stdio.h>
void bump(int *s, int n, int k) {
    int i;
    for (i = 0; i < n; i++)
        s[i] = s[i] + k;
    k = k + 10;
}
int main(void) {
    int a[3] = {5, 1, 8};
    int k = 2;
    bump(a, 3, k);
    bump(a, 2, k);
    printf("%d %d %d %d",
           a[0], a[1], a[2], k);
    return 0;
}

